query:
*[_type == "post"]{
  "patch": {
    "id": _id,
    "set": {
      "title": select(
        title match "*" => {
          "en": title,
          "fr": "",
          "ar": ""
        },
        title
      ),
      "overview": {
        "en": select(
          overview.en != null => overview.en,
          overview[0]._type == "block" => overview,
          []
        ),
        "fr": coalesce(overview.fr, []),
        "ar": coalesce(overview.ar, [])
      }
    }
  }
}
